import { IGameServerResponse, ISubGameSessionInfo } from '@game-studio/server-comms';
// import { ArcadeTypes } from '@game-studio/shell-connection-types';

import { LegacyEvent } from './event-emitter';
import { Container, PointData } from 'pixi.js';
import { BaseChip } from '../cabinet/casino-cabinet/base-chip';
import { IChatSettingsOption } from '../views/settings-menu/chat-colours';
import { CompanionPanel } from '../models/companion-state';
import { HowToPlayOpenSource } from '..';

export interface IGlobalEvents {
    /**
     * Fired on Penpal and Hybrid connections when calling publishToast
     * @param {string} message The message to display in the toast
     */
    GLOBAL_TOAST_NOTIFICATION: (message: string) => void;
    /**
     * Fired by Penpal and Apps when a begin returns a TimeKeeper error
     * @param {number} timeKeeperLimit Time in minutes representing the users TimeKeeperLimit
     */
    GLOBAL_SHOW_TIMEKEEPER: (timeKeeperLimit: number) => void;
    /**
     * Fired by Penpal and Apps when a begin returns a RealityCheck error
     * @param {number} realityCheckLimit Time in minutes representing the RealityCheck limit
     */
    GLOBAL_SHOW_REALITYCHECK: (realityCheckLimit: number) => void;
    /**
     * Fired by the app and Shell connections
     * @param {Object} winnerData TopPrize data to display
     */
    // GLOBAL_TOP_PRIZE: (winnerData: ArcadeTypes.IArcadeWinnerData) => void;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    GLOBAL_TOP_PRIZE: (winnerData: any) => void;
    /**
     * Fired by the app and Shell connections
     * @param {Object} promoData The promo data to display
     */
    // GLOBAL_PROMO: (promoData: ArcadeTypes.IPromoDetails) => void;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    GLOBAL_PROMO: (promoData: any) => void;
    /**
     * Fired by the Penpal and Apps when a begin returns a LowBalance error
     * @param {number} balanceInPence The balance of the user as a raw number
     * @param {number | void} lowestStake optional The lowest stake for this game in subunits
     */
    GLOBAL_LOW_BALANCE: (balanceInPence: number, lowestStake?: number) => void;
    /**
     * Fired by cabinet if gameServer throws an error on begin and there was a lower stake available
     */
    GLOBAL_STAKE_ALERT: (code: number) => void;
    /**
     * Fired by the Penpal and Apps when a begin returns ab AccountLocked error
     */
    GLOBAL_ACCOUNT_LOCKED: () => void;
    /**
     * Fired by the user-prefs when oneHandedPlay is changed
     */
    GLOBAL_ONE_HANDED_SETTING_CHANGED: () => void;
    /**
     * Fired by Penpal and Apps when minimising the game
     */
    GLOBAL_SUSPEND: () => void;
    /**
     * Fired by Penpal and Apps when restoring the game after suspending
     */
    GLOBAL_RESUME: () => void;
    /**
     * Fired by Penpal and Apps when calling openMenu
     */
    GLOBAL_MENU_OPENED: () => void;
    /**
     * Fired by the EndGameValidator when validation fails
     */
    GLOBAL_ON_VALIDATION_ERROR: () => void;
    /**
     * Fired at the end of an orientaion-change after the device and app.vue have updated
     */
    GLOBAL_ORIENTATION_CHANGE: () => void;
    /**
     * Fired by the user model when freeplay balance increases
     * @param {number} newBalance The new number of free plays the user has
     */
    GLOBAL_FREE_PLAY_EARNED: (newBalance: number) => void;
    /**
     * Fired when a free game ends and there are no freeplay credits remaining, auto fired by the App.vue
     * @param {number} payout The payout after the all free plays have ended
     * @param {string} message The message to display the user after all free plays have ended
     */
    GLOBAL_FREE_PLAY_ENDED: (payout: number, message: string) => void;
    /**
     * Fired for Italy when a freeplay session needs to be created silently (no wallet popup)
     */
    GLOBAL_FREEPLAY_SESSION_START_ITALY: () => void;
    /**
     * Fired when the Italy freeplay session has been successfully created and the cabinet can be enabled
     */
    GLOBAL_FREEPLAY_ITALY_SESSION_READY: () => void;
    /**
     * Fired by Penpal when entering or exiting the settings route
     * @param {boolean} visible Whether the settings is visible or not
     */
    GLOBAL_SETTINGS_VISIBILITY_CHANGE: (visible: boolean) => void;
    /**
     * Fired by the Bootstrap when isLazyLoadComplete is set to true
     */
    GLOBAL_LAZY_LOAD_COMPLETE: () => void;
    /**
     * Fired in the Game.ts when the lazy load components have been initialised
     */
    GLOBAL_LAZY_INIT_COMPLETE: () => void;
    /**
     * Tracks the loading progress of the assets used for the splash screen
     */
    GLOBAL_LOADING_PROGRESS: (progress: number) => void;
    /**
     * Fired when the assets have finished loading.
    */
    GLOBAL_LOADING_COMPLETE: () => void;
    /** Fired by the splash screen when it has an intro video to play — signals app-root to wait before hiding splash. */
    SPLASH_VIDEO_ACTIVE: () => void;
    /** Fired by the splash screen when both the intro video and loading have completed. */
    SPLASH_INTRO_COMPLETE: () => void;
    /** Fired by the WalletView when the wallet is updated */
    GLOBAL_WALLET_UPDATED: () => void;
    /** Fired by the SessionView when a session is created */
    GLOBAL_SESSION_CREATED: (status: IGameServerResponse) => void;
    /**
     * Fired by the info popup when it is opened or closed but can be fored by 
     * @param {boolean} value identifies if the data should be dimmed or restored
     */
    GLOBAL_DIM_SESSION_DATA: (value: boolean) => void;
}

export interface IActionMenu {
    /** Fired when the lobby button is clicked */
    ACTION_MENU_LOBBY_CLICKED: () => void;
    /** Fired when the action menu content is opened/closed */
    ACTION_MENU_CONTENT_TOGGLE: () => void;
    /** Fired when prize league tournament results have been calculated and are ready to display */
    SHOW_PRIZE_LEAGUE_RESULTS: () => void;
}

export interface IPopupEvents {
    /**
     * Fired by the Cabinet when the Game Info button is clicked to toggle the popup.
     * May include a boolean to force the popup on or off instead of toggling
     * @param {boolean | void} visibility Used to force the visibility true or false instead of toggling
     */
    POPUP_TOGGLE_GAME_INFO: (visibility: boolean | void, source?: HowToPlayOpenSource) => void;
    /**
     * Fired when showing or hiding the Debug Vue. Will include a boolean of true if the popup should display or false if it should hide
     * @param {boolean | void} visibility Used to force the visibility true or false instead of toggling
     */
    POPUP_TOGGLE_DEBUG_OVERLAY: (visibility: boolean | void) => void;
    /**
     * Intended to fire when the HTP is shown on desktop, or the new style HTP is shown
     * @param {boolean | void} visibility Used to force the visibility true or false instead of toggling
     */
    POPUP_TOGGLE_HTP_POPUP: (visibility: boolean | void, source?: HowToPlayOpenSource) => void;
    /**
     * Intended to fire when the HTP nudge is shown.
     * Used by the game to activate the nudge for new players (emit true on init).
     * @param {boolean | void} visibility Used to force the visibility true or false instead of toggling
     */
    POPUP_TOGGLE_HTP_NUDGE_POPUP: (visibility: boolean | void) => void;
    /**
     * Fired by the HTP view when the player actually opens or closes the HTP panel.
     * Distinct from POPUP_TOGGLE_GAME_INFO — this only fires on genuine user interaction.
     * @param {boolean} isOpen true when HTP opened, false when HTP closed
     */
    POPUP_HTP_VISIBILITY_CHANGED: (isOpen: boolean) => void;
    /**
     * Fired by Penpal when entering or exiting the old style HTP
     * @param {boolean} visibility Whether to show or hide the popup
     */
    POPUP_TOGGLE_OLD_HTP: (visibility: boolean) => void;
    /**
     * Fired by the app callbacks when entering or exiting the game rules directly
     * @param {boolean} visibility Whether to show or hide the popup
     */
    POPUP_TOGGLE_GAME_RULES: (visibility: boolean) => void;
    /** Fired by the UKGameServer on a Wallet Error */
    POPUP_SHOW_WALLET: (response: IGameServerResponse) => void;
    /** Fired by the Cabinet when attempting to buy in without active Session Data */
    POPUP_SHOW_SESSION: (response: ISubGameSessionInfo) => void
    /** Fired by the Cabinet when the cabinet enters freeplays to hide the initial popup so that it can 
     * be populated with freeplays information on purchase fail.
     */
    POPUP_HIDE_SESSION: () => void
}

export interface ICabinetEvents {
    /**
     * Fired by the BaseCabinet when increasing/decreasing stake
     */
    CABINET_STAKE_CHANGE: () => void;
    /**
     * Fired by the BaseCabinet when a Begin Request is sent, before a response is received. Sent with a boolean indicating if the Begin was initiated via an autoBuy which could be used to start some form of auto reveal
     */
    CABINET_BEGIN_SENT: () => void;
    /**
     * Fired by the BaseCabinet on clicking the actionButton in reveal Mode with singleReveal enabled
     */
    CABINET_REVEAL_NEXT: () => void;
    /**
     * Fired by the BaseCabinet on clicking the actionButton in reveal Mode with revealAll enabled or when holding the actionButton in reveal Mode with singleReveal and revealAll enabled
     */
    CABINET_START_REVEAL_ALL: () => void;
    /**
     * Fired by the BaseCabinet on clicking the actionButton while a revealAll is running
     */
    CABINET_STOP_REVEAL_ALL: () => void;
    /**
     * Fired by the BaseCabinet on clicking the actionButton while in the bonus state
     * @param {string} stateName The name of the current bonus state
     */
    CABINET_BONUS_ACTION: (stateName: string) => void;
}

export interface ICasinoCabinetEvents {
    CASINO_CABINET_DRAG_CHIP_RELEASED: (globalPoint: PointData, chipID: number) => void;
    CASINO_CABINET_DRAG_CHIP_PLACED: (globalPoint: PointData, chipID: number) => void;
    CASINO_CABINET_DRAG_CHIP_STARTED: (globalPoint: PointData, chip: BaseChip) => void;
    CASINO_CABINET_CLEAR: () => void;
    CASINO_CABINET_UNDO: () => void;
    CASINO_CABINET_REPEAT: () => void;
    CASINO_CABINET_CHIP_SELECTED: (chipID: number) => void;
    CASINO_CABINET_CHIP_SELECTED_NO_DRAG: (chipID: number, chip: BaseChip) => void;
}

export interface IGameEvents {
    /**
     * Fired by the Cabinet after receiving and processing a successful response from a Begin request
     * @param {boolean} isAutoBuying Signifies if the Begin was via the autoBuy feature
     */
    GAME_BEGIN: (isAutoBuying: boolean) => void;
    /**
     * Fired by the BaseCabinet in the endGame step
     */
    GAME_COMPLETE: () => void;
    /**
     * Intended to be fored by the game when a jackpot prize is added, updates session balance
     */
    GAME_JACKPOT_WIN: (prize: number) => void;
    /**
     * Intended to be fired by the game when triggering a Swipe To Buy action, never fired by the Base Package
     */
    GAME_SWIPE_TO_BUY: () => void;
    /**
     * Fired on a successful begin request if the user is in demo mode with 0 demo plays remaining
     */
    GAME_DEMO_OUT_OF_PLAYS: () => void;
}

export interface IChatEvents {
    /**
     * Fired when the fullscreen toggle button is clicked in chat.
     */
    CHAT_TOGGLE_FULL_SCREEN: () => void;
    CHAT_COLOURS_PROVIDED: (payload: IChatSettingsOption[]) => void;
}

export interface ICompanionEvents {
    COMPANION_PANEL_CHANGED: (panel: CompanionPanel) => void;
}

export interface IDebugEvents {
    DEBUG_INSPECTOR_ELEMENT_SELECTED: (selectedElement: Container | null) => void;
    DEBUG_INSPECTOR_SHOW_REQUESTED: (show: boolean) => void;
    DEBUG_ENGINE_VERSION_SET: (engineNumber: string) => void;
}

export type TCombinedEvents = IGlobalEvents & IActionMenu & IPopupEvents & ICabinetEvents & ICasinoCabinetEvents & IGameEvents & IDebugEvents & IChatEvents & ICompanionEvents;

